    'Ein Workspace hat eigene Videos, Leute und Review-Links. Du bist sein Owner; niemand sonst sieht ihn, bis du jemanden einlädst.',
  'An account sees every project in this workspace. For anyone else, share a review link from the player or a folder instead.':
    'Ein Konto sieht jedes Projekt in diesem Workspace. Für alle anderen teilst du besser einen Review-Link aus dem Player oder einem Ordner.',
  'Create workspace': 'Workspace anlegen',
  'Everyone in this workspace sees its whole library; other workspaces see none of it. <0>Reviewers</0> watch, write notes, check fixes and approve; <1>members</1> also upload, organize, share and assign agents. Everyone else reviews without an account: share a link from the player instead.':
    'Alle in diesem Workspace sehen seine ganze Bibliothek; andere Workspaces sehen nichts davon. <0>Reviewer</0> schauen, schreiben Notizen, prüfen Korrekturen und geben frei; <1>Mitglieder</1> laden außerdem hoch, ordnen, teilen und weisen Agenten zu. Alle anderen brauchen kein Konto: Teile stattdessen einen Link aus dem Player.',
  'Everyone with an account here, in a role of this workspace. People on review links never count.':
    'Alle mit einem Konto hier, mit einer Rolle in diesem Workspace. Wer über Review-Links schaut, zählt nie mit.',
  'For another team or brand: its own videos, people and review links. You’ll be its owner.':
    'Für ein anderes Team oder eine andere Marke: eigene Videos, Leute und Review-Links. Du wirst sein Owner.',
  HERE: 'HIER',
  'It works in <0>{workspace}</0> only.': 'Sie arbeitet nur in <0>{workspace}</0>.',
