  'The free plan. Choose a plan when you need room for more people, storage or videos.':
    'Der kostenlose Plan. Wähle einen Plan, sobald du Platz für mehr Leute, Speicher oder Videos brauchst.',
  'Cancelled: it ends on {date}, then the workspace moves to the free plan. Nothing is deleted.':
    'Gekündigt: Er endet am {date}, dann wechselt der Workspace zum kostenlosen Plan. Nichts wird gelöscht.',
  'Billed yearly, renews on {date}.': 'Jährlich abgerechnet, verlängert sich am {date}.',
